// src/commercial/growth-review.mjs
var e = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
var clean = (s) => String(s || "").replace(/｜周洋起草/g, "");
function reviewState(records = [], hasData = false) {
  const statuses2 = records.map((r) => String(r?.status || ""));
  if (statuses2.some((s) => /^(needs_changes|needsChanges|changes|blocked|待修改|需修改|返修|受阻)$/.test(s))) return { key: "changes", label: "需修改" };
  if (statuses2.length && statuses2.every((s) => /^(accepted|done|approved|已通过|已验收)$/.test(s))) return { key: "approved", label: "已通过" };
  return hasData ? { key: "data", label: "有资料" } : { key: "empty", label: "待补" };
}
function categoryState(D, c) {
  const posts = (D.content || []).filter((p) => c.posts.includes(p.id));
  return reviewState(posts, !!(c.templates.length || posts.length));
}
var badge = (s) => `<span class="review-state status-${s.key}">${s.label}</span>`;
var heading = (name, subtitle = "") => `<div class="growth-section-head"><div><h2>${e(name)}</h2>${subtitle ? `<p class="review-subtitle">${e(subtitle)}</p>` : ""}</div></div>`;
var task = (D, pattern) => (D.tasks || []).find((t) => pattern.test(t.title));
var node = (t) => t ? [t.date, t.time].filter(Boolean).join(" · ") || "待排期" : "待排期";
var block = (name, body) => `<section class="review-block"><h3>${name}</h3>${body}</section>`;
var safeLink = (url) => {
  try {
    const u = new URL(url);
    return ["https:", "buzz:"].includes(u.protocol) && !u.username && !u.password ? e(url) : "";
  } catch {
    return "";
  }
};
var matches = (name, c) => {
  const patterns = { countdown: /倒计时|报时|逐日/, launch: /新品|产品|穿越|包装/, holiday: /节日|季节|礼物/ };
  return (patterns[c.id] || new RegExp(c.name)).test(name);
};
function references(D, c) {
  const videos = (D.videos || []).filter((v) => matches(v.name, c));
  const playable = videos.filter((v) => safeLink(v.video));
  const notes = (D.plan?.references || []).filter((v) => matches(v.name, c) && safeLink(v.url));
  return `<div class="review-video-list">${playable.length ? playable.map((v) => `<figure><video controls playsinline preload="metadata" src="${safeLink(v.video)}"${safeLink(v.poster) ? ` poster="${safeLink(v.poster)}"` : ""}></video><figcaption>${e(v.name)}</figcaption></figure>`).join("") : `<div class="review-video-empty"><span>▶</span><strong>${e(c.name)}参考视频</strong><p>待补原片或可播放链接</p></div>`}</div>${notes.length ? `<details><summary>已有参考笔记 · 原片仍待核</summary>${notes.map((n) => `<p><a href="${safeLink(n.url)}" target="_blank" rel="noopener noreferrer">${e(n.name)} ↗</a></p>`).join("")}</details>` : ""}`;
}
